"""ROS logging bridge kept as Python in the binary SDK.

rclpy keys logging contexts by Python caller frame. Native callbacks otherwise
share the executor frame, causing mixed severities to raise ValueError.
Separate functions preserve a stable caller for each severity without using
private rclpy APIs. Message throttling remains with the calling nodes.
"""


def info(logger, message):
    return logger.info(message)


def warning(logger, message):
    return logger.warning(message)


def error(logger, message):
    return logger.error(message)
